file-session.head:
import { postSession } from "./api";

export interface Session {
  id: string;
  accountId: string;
}

export async function createSession(accountId: string) {
  const response = await postSession({ accountId });
  return response;
}

// The request captures the selected account.
// Callers must check that it is still selected
// after awaiting this asynchronous boundary.
export function isSessionForAccount(
  session: Session,
  accountId: string,
) { return session.accountId === accountId; }
// No automatic cancellation is performed here.

