import { createSession } from "./session";
import { selectedAccount, navigate, notify } from "./ui";

// Entry point used by the checkout button.
// The current account may change during a request.
// Navigation uses the session returned by the API.
// Supporting UI functions are outside this excerpt.

// Create and open checkout.
export async function startCheckout() {
  const session = await createSession();
  navigate(`/checkout/${session.id}`);
}
