file-checkout.head:
import { createSession } from "./session";
import { selectedAccount, navigate, notify } from "./ui";

// Entry point used by the checkout button.
// The current account may change during a request.
// Navigation uses the session returned by the API.
// Supporting UI functions are outside this excerpt.

// Create and open checkout for the selected account.
export async function startCheckout() {
  const accountId = selectedAccount.get()?.id;
  if (!accountId) {
    notify("Choose an account first");
    return;
  }
  const session = await createSession(accountId);
  navigate(`/checkout/${session.id}`);
}

file-api.base:
export async function postSession(input: { accountId?: string }) {
  const response = await fetch("/api/checkout/session", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(input),
  });
  if (!response.ok) throw new Error("Session request failed");
  const session = await response.json();
  return session; // Owned by the account captured in input.
}

